import pandas as pd, numpy as np, re

df = pd.read_csv('benchmark/data.csv')

def parse_inr(x):
    if pd.isna(x):
        return np.nan
    s=str(x)
    s=s.replace('₹','').replace(',','').strip()
    # handle blanks
    if s=='' or s.lower()=='nan':
        return np.nan
    try:
        return float(s)
    except:
        return np.nan

def parse_pct(x):
    if pd.isna(x):
        return np.nan
    s=str(x).replace('%','').strip()
    if s=='':
        return np.nan
    try:
        return float(s)
    except:
        return np.nan

def parse_int(x):
    if pd.isna(x):
        return np.nan
    s=str(x).replace(',','').strip()
    if s=='':
        return np.nan
    try:
        return int(float(s))
    except:
        return np.nan

def parse_rating(x):
    if pd.isna(x):
        return np.nan
    s=str(x).strip()
    # some are like '4.1|...' keep first numeric
    m=re.search(r"(\d+(?:\.\d+)?)", s)
    return float(m.group(1)) if m else np.nan

cdf=df.copy()
cdf['discounted_price_num']=cdf['discounted_price'].map(parse_inr)
cdf['actual_price_num']=cdf['actual_price'].map(parse_inr)
cdf['discount_pct_num']=cdf['discount_percentage'].map(parse_pct)
cdf['rating_num']=cdf['rating'].map(parse_rating)
cdf['rating_count_num']=cdf['rating_count'].map(parse_int)

print('missing rating', cdf['rating_num'].isna().sum())
print('missing rating_count', cdf['rating_count_num'].isna().sum())
print('discount_pct min/max', cdf['discount_pct_num'].min(), cdf['discount_pct_num'].max())

# top-level category
cdf['cat_lvl1']=cdf['category'].astype(str).str.split('|').str[0]

# KPIs
avg_rating=cdf['rating_num'].mean()
avg_disc=cdf['discount_pct_num'].mean()
median_rating_count=cdf['rating_count_num'].median()
high_share=(cdf['rating_num']>=4.0).mean()
print(avg_rating, avg_disc, median_rating_count, high_share)

# correlations
sub=cdf[['discount_pct_num','rating_num','rating_count_num','discounted_price_num','actual_price_num']].dropna()
print('corr disc-rating', sub['discount_pct_num'].corr(sub['rating_num']))
print('corr disc-rating_count', sub['discount_pct_num'].corr(sub['rating_count_num']))
print('n corr', len(sub))
